$target = Join-Path $PSScriptRoot '..\admin-panel\app\quran\page.tsx'
$source = Get-Content -LiteralPath $target -Raw
$source = $source.Replace('[saving,setSaving]=useState(false);','[saving,setSaving]=useState(false),[languageOpen,setLanguageOpen]=useState(false),[languageSearch,setLanguageSearch]=useState("");')
$pattern = '<label>Step 1[^<]*Content language<select value=\{language\} onChange=\{e=>setLanguage\(e\.target\.value\)\}>.*?</select></label><label>Step 2'
$replacement = @'
<label className="languagePickerLabel">Step 1 â€” Content language<button type="button" className="languagePickerButton" onClick={()=>setLanguageOpen(true)}><span><i>{language.toUpperCase()}</i><b>{languages.find(x=>x.code===language)?.label||language.toUpperCase()}</b></span>{(surahs.find(s=>s.number===surahNo)?.translationProgress?.[language]||0)>0?<em>âœ“ SAVED</em>:<em className="missing">NOT UPLOADED</em>}<strong>âŒ„</strong></button></label><label>Step 2
'@
$replacement = $replacement.Trim()
$selectorRegex = [regex]::new($pattern,[System.Text.RegularExpressions.RegexOptions]::Singleline)
$updated = $selectorRegex.Replace($source,[System.Text.RegularExpressions.MatchEvaluator]{param($m)$replacement},1)
if ($updated -eq $source) { throw 'Native language select marker not found' }
$source = $updated
$modal = @'
{languageOpen&&<div className="languageModal" role="dialog" aria-modal="true" aria-label="Select Quran content language"><section><div className="languageModalHead"><div><small>QURAN CONTENT</small><h2>Select Language</h2><p>{savedLanguages.length} languages uploaded for {surah?.englishName||"this Surah"}</p></div><button type="button" onClick={()=>{setLanguageOpen(false);setLanguageSearch("")}}>Ã—</button></div><label className="languageSearch"><span>âŒ•</span><input autoFocus value={languageSearch} onChange={e=>setLanguageSearch(e.target.value)} placeholder="Search language or code..."/></label><div className="languageList">{languages.filter(item=>item.code!=="en"&&(!languageSearch.trim()||`${item.label} ${item.code}`.toLowerCase().includes(languageSearch.trim().toLowerCase()))).map(item=>{const count=surahs.find(s=>s.number===surahNo)?.translationProgress?.[item.code]||0,total=surah?.ayahs?.length||surahs.find(s=>s.number===surahNo)?.numberOfAyahs||0,complete=count===total&&total>0;return <button type="button" key={item.code} className={language===item.code?"languageRow selected":"languageRow"} onClick={()=>{setLanguage(item.code);setLanguageOpen(false);setLanguageSearch("")}}><i>{item.code.slice(0,3).toUpperCase()}</i><span><b>{item.label}</b><small>{complete?`${count}/${total} Ayahs â€” Complete`:count?`${count}/${total} Ayahs â€” In progress`:"Not uploaded"}</small></span>{count>0?<em>âœ“</em>:<em className="emptyMark"/>}<strong>â€º</strong></button>})}</div></section></div>}
'@
$modal = $modal.Trim()
$styleMarker = '<style jsx>{`'
$first = $source.IndexOf($styleMarker)
if ($first -lt 0) { throw 'First style marker not found' }
$source = $source.Insert($first,$modal)
$lastMain = '</main>'
$css = @'
<style jsx>{`
.languagePickerLabel{display:block}.languagePickerButton{width:100%;height:46px;margin-top:6px;padding:6px 10px;display:flex;align-items:center;gap:9px;border:1px solid #b9d4c2;border-radius:10px;background:#fff;color:#173d2e;box-shadow:none}.languagePickerButton>span{display:flex;align-items:center;gap:8px;min-width:0;flex:1}.languagePickerButton>span i{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:#e8f4eb;color:#087a4d;font-size:8px;font-style:normal}.languagePickerButton>span b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.languagePickerButton>em{padding:5px 7px;border-radius:7px;background:#e0f3e6;color:#087a4d;font-size:8px;font-style:normal}.languagePickerButton>em.missing{background:#f3f5f3;color:#819087}.languagePickerButton>strong{font-size:17px;color:#087a4d}
.languageModal{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:rgba(11,39,29,.58);backdrop-filter:blur(4px)}.languageModal>section{width:min(520px,100%);max-height:min(760px,92vh);display:flex;flex-direction:column;padding:20px;border:1px solid #d8e6dc;border-radius:24px;background:#fbfdfb;box-shadow:0 28px 80px rgba(5,35,23,.3);animation:languageOpen .22s ease-out}@keyframes languageOpen{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}.languageModalHead{display:flex;align-items:flex-start;gap:16px}.languageModalHead>div{flex:1}.languageModalHead small{color:#aa852a;font-size:8px;font-weight:900;letter-spacing:1.2px}.languageModalHead h2{margin:4px 0 2px;font:700 27px Georgia,serif}.languageModalHead p{margin:0;color:#718078;font-size:10px}.languageModalHead>button{width:38px;height:38px;padding:0;border-radius:50%;background:#e7f3ea;color:#087a4d;font-size:21px}.languageSearch{position:relative;display:block;margin:16px 0 12px}.languageSearch span{position:absolute;left:14px;top:18px;color:#087a4d;font-size:18px}.languageSearch input{height:48px;margin:0;padding-left:42px;border-radius:13px;background:#fff}.languageList{display:grid;gap:8px;overflow:auto;padding:2px 4px 4px 0}.languageRow{width:100%;min-height:64px;padding:9px 12px;display:flex;align-items:center;gap:11px;border:1px solid #dce7df;border-radius:15px;background:#fff;color:#344f43;text-align:left;box-shadow:0 2px 5px rgba(23,61,46,.035);transition:.18s ease}.languageRow:hover,.languageRow.selected{transform:translateY(-1px);border-color:#83b798;background:#f4fbf6;box-shadow:0 7px 16px rgba(23,61,46,.08)}.languageRow>i{width:40px;height:40px;display:grid;place-items:center;flex:0 0 auto;border-radius:50%;background:#edf3ef;color:#64776d;font-size:8px;font-style:normal;font-weight:900}.languageRow>span{min-width:0;flex:1}.languageRow>span b,.languageRow>span small{display:block}.languageRow>span b{font-size:13px}.languageRow>span small{margin-top:4px;color:#849188;font-size:9px}.languageRow>em{width:20px;height:20px;display:grid;place-items:center;border-radius:50%;background:#07925b;color:#fff;font-size:11px;font-style:normal;font-weight:900}.languageRow>em.emptyMark{background:#edf2ee}.languageRow>strong{color:#087a4d;font-size:19px}.languageList:empty:after{content:"No matching language found";display:block;padding:45px;text-align:center;color:#7b8a82}
`}</style>
'@
$endIndex = $source.LastIndexOf($lastMain)
if ($endIndex -lt 0) { throw 'Main closing marker not found' }
$source = $source.Insert($endIndex,$css.TrimEnd())
Set-Content -LiteralPath $target -Value $source -NoNewline -Encoding utf8
